	[2661]={
		encounterID=2661,
		instanceID=1300,
		order=2,
		name="Seranel Sunlash",
		lore="An accomplished Spellbreaker, Serenel Sunlash has earned the full trust of the Magisters. Charged with the protection of the Cynosure of Twilight, Seranel will fulfill those duties with his very life if necessary.",
		dungeonEncounterID=3072,
		uiMapID=2516,
		pin={x=0.559,y=0.3336},
		difficultyIDs={1,2,8,23,205},
		npcIDs={231863},
