	[2662]={
		encounterID=2662,
		instanceID=1300,
		order=4,
		name="Degentrius",
		lore="A powerful creature of the Void, Degentrius has taken advantage of the opportunity inadvertently provided by Magister Umbric and launched an assault on the Terrace.",
		dungeonEncounterID=3074,
		uiMapID=2520,
		pin={x=0.5024,y=0.5049},
		difficultyIDs={1,2,8,23,205},
