			{itemID=263230,diffs={},faction=-1},
			{itemID=260231,diffs={23},faction=-1},
		},
		sections={
			{id=30548,title="Overview",body="Degentrius leads the assault from atop Magisters' Terrace, commanding the platform with overwhelming Void magic. |cFF2959D3|Hspell:1214714|h[Void Torrent]|h|r streams carve across the arena as they flow into Degentrius, while |cFF2959D3|Hspell:1215087|h[Unstable Void Essence]|h|rs ricochet around the platform."},
			{id=30549,title="Damage Dealers",body="$bullet; If there are no players standing under |cFF2959D3|Hspell:1215087|h[Unstable Void Essence]|h|r  when it impacts, damage will be inflicted to all players.\n$bullet; |cFF2959D3|Hspell:1214714|h[Void Torrent]|h|r  inflicts moderate damage and stuns any players that come into contact with it."},
			{id=30550,title="Healers",body="$bullet; |cFF2959D3|Hspell:1215897|h[Devouring Entropy]|h|r creates Entropy Orbs upon removal.\n$bullet; If there are no players standing under |cFF2959D3|Hspell:1215087|h[Unstable Void Essence]|h|r  when it impacts, damage will be inflicted to all players.\n$bullet; |cFF2959D3|Hspell:1214714|h[Void Torrent]|h|r  inflicts moderate damage and stuns any players that come into contact with it."},
			{id=30551,title="Tanks",body="$bullet; |cFF2959D3|Hspell:1215941|h[Null Bomb]|h|r will inflict massive damage to all players if it is not triggered by a player.\n$bullet; If there are no players standing under |cFF2959D3|Hspell:1215087|h[Unstable Void Essence]|h|r  when it impacts, damage will be inflicted to all players.\n$bullet; |cFF2959D3|Hspell:1214714|h[Void Torrent]|h|r  inflicts moderate damage and stuns any players that come into contact with it."},
			{id=31276,title="Section 10"},
			{id=31274,title="Section 7"},
			{id=31275,title="Section 8"},
			{id=31292,title="Section 12"},
			{id=34557,title="Section 14"},
			{id=31278,title="Section 11",body="$[!23\n\nIn Mythic difficulty, |cFF2959D3|Hspell:1280113|h[Hulking Fragment]|h|r embeds |cFF2959D3|Hspell:1284627|h[Umbral Splinters]|h|r into the target.$]"},
