		instanceID=1304,
		order=0,
		name="Kystia Manaheart",
		lore="Although an accomplished Magister, Kystia Manaheart was far too devoted to fel magic to give it up entirely. Little wonder she's become a staunch supporter and ally to underground fel smuggling operations in the Row.",
		dungeonEncounterID=3101,
		uiMapID=2433,
