			{itemID=251135,diffs={},faction=-1},
			{itemID=251134,diffs={},faction=-1},
		},
		sections={
			{id=31293,title="Overview",body="Xathuux the Annihilator's rage increases until he erupts with |cFF2959D3|Hspell:474197|h[Demonic Rage]|h|r and gains |cFF2959D3|Hspell:474231|h[Burning Steps]|h|r."},
			{id=31294,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:474231|h[Burning Steps]|h|r leaves damaging pools of fel magic on the ground for a long duration.\n\n$bullet;|cFF2959D3|Hspell:1214637|h[Axe Toss]|h|r targets a random player and applies |cFF2959D3|Hspell:1214650  |h[Fel Lightning]|h|r to all players until the axe is destroyed."},
			{id=31296,title="Healers",body="$bullet;|cFF2959D3|Hspell:473898|h[Legion Strike]|h|r inflicts heavy Physical damage and reduces incoming healing.\n\n$bullet;|cFF2959D3|Hspell:1214637|h[Axe Toss]|h|r targets a random player and applies |cFF2959D3|Hspell:1214650  |h[Fel Lightning]|h|r to all players until the axe is destroyed."},
			{id=31295,title="Tanks",body="$bullet;|cFF2959D3|Hspell:473898|h[Legion Strike]|h|r inflicts heavy Physical damage and reduces incoming healing.\n\n$bullet;|cFF2959D3|Hspell:474231|h[Burning Steps]|h|r creates damaging pools of fel magic that expand from Xathuux the Annihilator's location and remain on the ground for a long duration."},
			{id=31298,title="Section 6"},
