	[2682]={
		encounterID=2682,
		instanceID=1304,
		order=4,
		name="Lithiel Cinderfury",
		lore="Lithiel Cinderfury sees the Voidstorm above Silvermoon as both threat and opportunity. Her people are afraid, and she has a perfect solution... the power of fel. She claims her smuggling operation protects her people from the dangers above, but the profits she receives are a pleasing bonus.",
		dungeonEncounterID=3105,
		uiMapID=2434,
		pin={x=0.4729,y=0.2154},
		difficultyIDs={1,2,8,23,205},
		npcIDs={55659,99737,134468,143622,230873},
		displayIDs={77407,84426,103096,124577},
		loot={
			{itemID=250255,diffs={},faction=-1},
			{itemID=251142,diffs={},faction=-1},
			{itemID=251139,diffs={},faction=-1},
