	[2733]={
		encounterID=2733,
		instanceID=1307,
		order=0,
		name="Imperator Averzian",
		lore="Imperator Averzian wages a relentless campaign, seeking not conquest, but annihilation. His entire will is bent to a singular ambition: to rend the veil between worlds and carve a breach into the Void itself. Through this wound, his infinite host shall pour forth, drowning Azeroth in darkness.",
		dungeonEncounterID=3176,
		uiMapID=2529,
		pin={x=0.3985,y=0.685},
		difficultyIDs={14,15,16,17,220},
		npcIDs={167233,240548,248148,248431,264858},
