		sections={
			{id=32171,title="Overview",body="Vorasius periodically strikes the ground with |cFF2959D3|Hspell:1244012|h[Shadowclaw Slam]|h|r, creating crystals that divide the battlefield. The behemoth then shakes off parasitic creeps that explode in a |cFF2959D3|Hspell:1259184|h[Blisterburst]|h|r upon death.\n\nAs the battle rages, Vorasius sweeps his deadly |cFF2959D3|Hspell:1241864|h[Void Breath]|h|r from one side of the battlefield to the other, decimating anything caught in its path."},
			{id=32172,title="Damage Dealers",body="$bullet; The explosion of |cFF2959D3|Hspell:1259184|h[Blisterburst]|h|r  is powerful enough to damage Void Crystals.\n\n$bullet; |cFF2959D3|Hspell:1244012|h[Shadowclaw Slam]|h|r causes reverberating |cFF2959D3|Hspell:1273067|h[Aftershocks]|h|r from its impact location."},
			{id=32173,title="Healers",body="$bullet; The explosion of |cFF2959D3|Hspell:1259184|h[Blisterburst]|h|r  is powerful enough to damage Void Crystals.\n\n$bullet; |cFF2959D3|Hspell:1260046|h[Primordial Roar]|h|r causes Vorasius to gain more |cFF2959D3|Hspell:1272937|h[Primordial Power]|h|r with each cast."},
			{id=32174,title="Tanks",body="$bullet; |cFF2959D3|Hspell:1244012|h[Shadowclaw Slam]|h|r inflicts deadly damage to the raid if it fails to hit at least one player.\n\n$bullet; |cFF2959D3|Hspell:1244419|h[Overpowering Pulse]|h|r is triggered when no enemies are near Vorasius."},
			{id=33252,title="Section 10"},
			{id=35412,title="Section 20"},
			{id=33247,title="Section 7"},
			{id=33248,title="Blistercreep",body="A parasitic spawn that fixates on a player."},
			{id=33249,title="Section 12",body="$[!16 \n\nOn Mythic difficulty, Blisterburst leaves behind Dark Goo.$]"},
			{id=34916,title="Section 18"},
			{id=33253,title="Section 11",difficultyIDs={16}},
			{id=33250,title="Section 9"},
			{id=34201,title="Section 16"},
			{id=34911,title="Section 19"},
