	[2735]={
		encounterID=2735,
		instanceID=1307,
		order=3,
		name="Vaelgor & Ezzorak",
		lore="Born as clutchmates in the red dragonflight, Vaelgor and Ezzorak were once the guardians of all living things. Now, twisted by the dark will of Xal'atath, all that remains of their former selves is their unyielding bond to one another.",
		dungeonEncounterID=3178,
