		sections={
			{id=32187,title="Overview",body="Alleria Windrunner begins the fight held back by Undying Sentinels from the Void. She periodically strikes out at friend and foe alike with both Void effects and |cFF2959D3|Hspell:1233602|h[Silverstrike Arrow]|h|r. \n\nWhen each of the Undying Sentinels have been destroyed, Alleria crashes into the platform and creates a Rift Simulacrum to assault her enemies with |cFF2959D3|Hspell:1237837|h[Call of the Void]|h|r and |cFF2959D3|Hspell:1237614|h[Ranger Captain's Mark]|h|r.\n\nWhen the Rift Simulacrum is shattered, Alleria releases her full Void abilities upon all players."},
			{id=32188,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:1233602|h[Silverstrike Arrow]|h|r will remove any Void effects from targets struck.\n$bullet;Void Droplet will splash targets with |cFF2959D3|Hspell:1241520|h[Corrupting Essence]|h|r when it dies.\n$bullet;|cFF2959D3|Hspell:1239080|h[Aspect of the End]|h|r reduces healing received until the target moves away from the arrow."},
			{id=32189,title="Healers",body="$bullet;|cFF2959D3|Hspell:1233602|h[Silverstrike Arrow]|h|r will remove any Void effects from targets struck.\n$bullet;|cFF2959D3|Hspell:1233865|h[Null Corona]|h|r absorbs a large amount of healing and can be moved to another player when dispelled.\n$bullet;|cFF2959D3|Hspell:1239080|h[Aspect of the End]|h|r reduces healing received until the target moves away from the arrow."},
			{id=33345,title="Tanks",body="$bullet;Undying Sentinels utilize |cFF2959D3|Hspell:1239279|h[Echoing Darkness]|h|r when no players are in melee combat.\n$bullet;|cFF2959D3|Hspell:1237251|h[Empowering Darkness]|h|r affects Alleria's allies within a large area.\n$bullet;|cFF2959D3|Hspell:1239080|h[Aspect of the End]|h|r reduces healing received and |cFF2959D3|Hspell:1239089|h[Gravity Collapse]|h|r leaves the target weak to Physical attacks.",difficultyIDs={14,17}},
			{id=32190,title="Tanks",body="$bullet;Undying Sentinels utilize |cFF2959D3|Hspell:1233778|h[Echoing Darkness]|h|r when no players are in melee combat.\n$bullet;|cFF2959D3|Hspell:1237251|h[Empowering Darkness]|h|r affects Alleria's allies within a large area.\n$bullet;|cFF2959D3|Hspell:1239080|h[Aspect of the End]|h|r reduces healing received and |cFF2959D3|Hspell:1239089|h[Gravity Collapse]|h|r leaves the target weak to Physical attacks.",difficultyIDs={15,16}},
