	[2739]={
		encounterID=2739,
		instanceID=1308,
		order=0,
		name="Belo'ren, Child of Al'ar",
		lore="One of the last clutch of Al'ar, Belo'ren was raised for the purpose of protecting the Isle of Quel'Danas. In the aftermath of the Voidspire, Belo'ren has been irradiated by Void. Confused and freshly hatched, the phoenix is focused on its sole task: Keep any invaders from reaching the Sunwell.",
		dungeonEncounterID=3182,
		uiMapID=2533,
		pin={x=0.5103,y=0.3017},
		difficultyIDs={14,15,16,17,220},
		npcIDs={249637},
		displayIDs={128558,128559,130007},
		loot={
