	[2740]={
		encounterID=2740,
		instanceID=1308,
		order=1,
		name="Midnight Falls",
		lore="Once a creature of Light, L'ura fell to the Void long ago on Argus, her essence siphoned by Alleria Windrunner in the Seat of the Triumvirate. Freed from her bindings, L'ura's dark energies now threaten the very Sunwell itself.",
		dungeonEncounterID=3183,
		uiMapID=2534,
		pin={x=0.5103,y=0.4409},
		difficultyIDs={14,15,16,17,220},
		npcIDs={214650},
		displayIDs={129561,136356,136357,138946},
		loot={
			{itemID=249811,diffs={},faction=-1},
			{itemID=249810,diffs={},faction=-1},
