	[2769]={
		encounterID=2769,
		instanceID=1309,
		order=1,
		name="Lightblossom Trinity",
		lore="The Lightbloom has suffered a terrible defeat, but like the rutaani it imbues, it changes. These Lightblossomed rutaani fanatically propagate their vicious and invasive garden.",
		dungeonEncounterID=3199,
		uiMapID=2500,
		pin={x=0.5208,y=0.2535},
		difficultyIDs={1,2,8,23,205},
		npcIDs={243028,243029,243030},
		displayIDs={129261,129588,139025,139027},
		loot={
			{itemID=251185,diffs={},faction=-1},
			{itemID=251183,diffs={},faction=-1},
			{itemID=251184,diffs={},faction=-1},
			{itemID=251182,diffs={},faction=-1},
			{itemID=251180,diffs={},faction=-1},
			{itemID=251181,diffs={},faction=-1},
			{itemID=250254,diffs={},faction=-1},
		},
		sections={
			{id=32314,title="Overview",body="The trio of Lightbloom rutaani work in tandem to sow and nurture a Lightblossom garden. Meittik creates |cFF2959D3|Hspell:1234782|h[Fertile Loam]|h|r that is then planted by Lekshi's |cFF2959D3|Hspell:1234850|h[Lightsower Dash]|h|r. Kezkitt rapidly germinates the flora with |cFF2959D3|Hspell:1235564|h[Lightblossom Beam]|h|r until they burst in a |cFF2959D3|Hspell:1235751|h[Lightbloom Overgrowth]|h|r."},
			{id=34343,title="Damage Dealers",body="$bullet; Lightblossoms gain an increasing amount of |cFF2959D3|Hspell:1235729|h[Light-Gorged]|h|r unless the rays of |cFF2959D3|Hspell:1235564|h[Lightblossom Beam]|h|r are blocked.\n$bullet; Damage taken is shared between the trio with |cFF2959D3|Hspell:1253028|h[Thicket's Trinity]|h|r."},
			{id=34906,title="Healers",body="$bullet; |cFF2959D3|Hspell:1235751|h[Lightbloom Overgrowth]|h|r inflicts higher damage based on applications of |cFF2959D3|Hspell:1235729|h[Light-Gorged]|h|r.\n$bullet; |cFF2959D3|Hspell:1235640|h[Thornblade]|h|r causes random players to bleed for high damage.",difficultyIDs={1,2}},
			{id=34344,title="Healers",body="$bullet; |cFF2959D3|Hspell:1235751|h[Lightbloom Overgrowth]|h|r inflicts higher damage based on applications of |cFF2959D3|Hspell:1235729|h[Light-Gorged]|h|r.\n$bullet; |cFF2959D3|Hspell:1235640|h[Thornblade]|h|r causes random players to bleed for high damage.\n$bullet; |cFF2959D3|Hspell:1276586|h[Bedrock Surge]|h|r inflicts periodic damage to all players.",difficultyIDs={8,23}},
			{id=34345,title="Tank",body="$bullet; |cFF2959D3|Hspell:1234753|h[Bedrock Slam]|h|r creates patches of |cFF2959D3|Hspell:1234782|h[Fertile Loam]|h|r near the location of the target.\n$bullet; Lightblossoms gain an increasing amount of |cFF2959D3|Hspell:1235729|h[Light-Gorged]|h|r unless the rays of |cFF2959D3|Hspell:1235564|h[Lightblossom Beam]|h|r are blocked."},
			{id=33927,title="Section 16"},
			{id=32514,title="Meittik"},
			{id=34903,title="Bedrock Slam",difficultyIDs={1,2}},
			{id=34904,title="Fertile Loam"},
			{id=32515,title="Bedrock Slam",body="$[!8,23,\n\nOn Mythic difficulty, Bedrock Slam causes a Bedrock Surge.$]",difficultyIDs={8,23}},
