	[2770]={
		encounterID=2770,
		instanceID=1309,
		order=2,
		name="Ikuzz the Light Hunter",
		lore="Ikuzz is a fearsome carnivore who once stalked prey throughout Harandar. Now the Light Hunter has succumbed to the overwhelming power of the Lightbloom, and his insatiable hunger serves its growth.",
		dungeonEncounterID=3200,
		uiMapID=2500,
		pin={x=0.5283,y=0.5737},
		difficultyIDs={1,2,8,23,205},
		npcIDs={244887},
		displayIDs={28634,129424},
		loot={
			{itemID=251190,diffs={},faction=-1},
			{itemID=251189,diffs={},faction=-1},
			{itemID=251187,diffs={},faction=-1},
			{itemID=251186,diffs={},faction=-1},
			{itemID=251188,diffs={},faction=-1},
			{itemID=250238,diffs={},faction=-1},
		},
		sections={
			{id=32315,title="Overview",body="Ikuzz entangles players in |cFF2959D3|Hspell:1236658|h[Bloodthorn Roots]|h|r to immobilize his prey. At 100 energy, he fixates on a player with a |cFF2959D3|Hspell:1237090|h[Bloodthirsty Gaze]|h|r and attempts to |cFF2959D3|Hspell:1237166|h[Incise]|h|r them."},
			{id=33031,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:1236658|h[Bloodthorn Roots]|h|r immobilize players until the roots are destroyed.\n$bullet; Players targeted by |cFF2959D3|Hspell:1237090|h[Bloodthirsty Gaze]|h|r will be |cFF2959D3|Hspell:1237166|h[Incised]|h|r if Ikuzz reaches their location."},
			{id=33032,title="Healers",body="$bullet; |cFF2959D3|Hspell:1236658|h[Bloodthorn Roots]|h|r immobilize players until the roots are destroyed.\n$bullet; |cFF2959D3|Hspell:1236709|h[Thorncaller Roar]|h|r channels Nature damage on all players.\n$bullet; Players take a high amount of damage when |cFF2959D3|Hspell:1237166|h[Incised]|h|r."},
			{id=33033,title="Tank",body="$bullet; |cFF2959D3|Hspell:1236658|h[Bloodthorn Roots]|h|r immobilize players until the roots are destroyed.\n$bullet; Players targeted by |cFF2959D3|Hspell:1237090|h[Bloodthirsty Gaze]|h|r will be |cFF2959D3|Hspell:1237166|h[Incised]|h|r if Ikuzz reaches their location."},
			{id=32727,title="Section 2"},
			{id=32731,title="Section 5"},
			{id=32732,title="Section 6"},
			{id=32733,title="Section 7"},
			{id=34739,title="Section 13"},
			{id=34513,title="Section 15",difficultyIDs={1,2,205}},
			{id=32728,title="Section 3",body="$[!8,23,\n\nOn Mythic difficulty, Bloodthorn Roots emerge at players' locations after Verdant Stomp.$]",difficultyIDs={8,23}},
			{id=32730,title="Section 4"},
			{id=32734,title="Section 8"},
		},
	},
	[2771]={
		encounterID=2771,
		instanceID=1309,
		order=3,
		name="Lightwarden Ruia",
		lore="The once-respected Rootwarden Ruia could not defeat the Lightbloom on his own. His wounded pride led him to drawing power from the Lightbloom and using it to punish all others instead of aiding his allies.",
		dungeonEncounterID=3201,
		uiMapID=2500,
		pin={x=0.8758,y=0.4263},
		difficultyIDs={1,2,8,23,205},
		npcIDs={245912},
		displayIDs={129856,129858,137347},
		loot={
			{itemID=250214,diffs={},faction=-1},
			{itemID=251194,diffs={},faction=-1},
