	[2772]={
		encounterID=2772,
		instanceID=1309,
		order=4,
		name="Ziekket",
		lore="Born from the Lightbloom's epicenter, Ziekket was spawned and incubated by Light-infested rutaani to create an unstoppable engine of the Lightbloom's expansion.",
		dungeonEncounterID=3202,
		uiMapID=2500,
		pin={x=0.4226,y=0.5},
		difficultyIDs={1,2,8,23,205},
		npcIDs={247676},
