	[2776]={
		encounterID=2776,
		instanceID=1311,
		order=1,
		name="The Hoardmonger",
		lore="Driven by voracious greed, the gluttonous Hoardmonger fiercely defends the stashes of food and supplies he has stolen from nearby troll tribes. Nalorakk's first trial is to eliminate him before the tribes go hungry.",
		dungeonEncounterID=3207,
		uiMapID=2514,
		pin={x=0.4561,y=0.6859},
		difficultyIDs={1,2,8,23,205},
		npcIDs={241812},
		displayIDs={129344,129345},
		loot={
			{itemID=250248,diffs={},faction=-1},
			{itemID=251148,diffs={},faction=-1},
			{itemID=251147,diffs={},faction=-1},
			{itemID=251146,diffs={},faction=-1},
			{itemID=251145,diffs={},faction=-1},
			{itemID=251144,diffs={},faction=-1},
			{itemID=251143,diffs={},faction=-1},
		},
		sections={
			{id=32669,title="Overview",body="The Hoardmonger prevents his reserves from being pilfered at all costs, casting |cFF2959D3|Hspell:1235072|h[Resourceful Measures]|h|r upon reaching $1309912s1%, $1309912s2%, and $1309912s3% health, empowering one of his abilities.\n\nUpon reaching 100 energy, he tosses |cFF2959D3|Hspell:1234233|h[Spoiled Supplies]|h|r throughout the arena, growing Rotten Mushrooms for 12 seconds. Upon contact, these apply |cFF2959D3|Hspell:1234846|h[Toxic Spores]|h|r destroying the fungi, preventing |cFF2959D3|Hspell:1245593|h[Putrid Burst]|h|r."},
			{id=32670,title="Damage Dealers",body="$bullet; Rotten Mushrooms apply |cFF2959D3|Hspell:1234846|h[Toxic Spores]|h|r upon contact, preventing them from detonating in a |cFF2959D3|Hspell:1245593|h[Putrid Burst]|h|r.\n$bullet; |cFF2959D3|Hspell:1234021|h[Earthshatter Slam]|h|r and |cFF2959D3|Hspell:1235129|h[Bonespike Slam]|h|r inflict massive damage in a frontal cone.\n$bullet; |cFF2959D3|Hspell:1234681|h[Ravenous Bellow]|h|r and |cFF2959D3|Hspell:1235125|h[Hearty Bellow]|h|r inflicts high damage to all players."},
			{id=32671,title="Healers",body="$bullet; |cFF2959D3|Hspell:1234681|h[Ravenous Bellow]|h|r and |cFF2959D3|Hspell:1235125|h[Hearty Bellow]|h|r inflict high damage to all players.\n$bullet; Rotten Mushrooms' |cFF2959D3|Hspell:1234846|h[Toxic Spores]|h|r can be removed by Poison-cleansing effects.\n$bullet; |cFF2959D3|Hspell:1234021|h[Earthshatter Slam]|h|r and |cFF2959D3|Hspell:1235129|h[Bonespike Slam]|h|r inflict massive damage in a frontal cone."},
			{id=32672,title="Tanks",body="$bullet; The Hoardmonger gathers from the nearest resource pile during |cFF2959D3|Hspell:1235072|h[Resourceful Measures]|h|r.\n$bullet; Rotten Mushrooms apply |cFF2959D3|Hspell:1234846|h[Toxic Spores]|h|r upon contact, preventing them from detonating in a |cFF2959D3|Hspell:1245593|h[Putrid Burst]|h|r.\n$bullet; |cFF2959D3|Hspell:1234681|h[Ravenous Bellow]|h|r and |cFF2959D3|Hspell:1235125|h[Hearty Bellow]|h|r inflict high damage to all players."},
			{id=32673,title="Section 1",difficultyIDs={1,2,205}},
			{id=32679,title="Section 2"},
			{id=32677,title="Section 5"},
			{id=32678,title="Section 13"},
			{id=32674,title="Section 6"},
			{id=32652,title="Section 1",body="$[!23,8\n\nIn Mythic difficulty, newly acquired abilities are permanent.$]",difficultyIDs={8,23}},
			{id=32658,title="Section 2"},
			{id=32656,title="Section 5"},
			{id=32657,title="Section 13"},
			{id=32654,title="Section 6"},
			{id=32659,title="Section 7"},
			{id=32665,title="Rotten Mushroom",body="This fungi grows for 12 seconds then detonates in a Putrid Burst, covering all players in Toxic Spores.\n\nUpon contact, the spores transfer, applying Toxic Spores and destroying the fungi."},
			{id=32661,title="Section 9"},
			{id=32662,title="Section 10"},
			{id=32663,title="Section 11"},
			{id=32664,title="Section 12"},
		},
	},
	[2777]={
