		instanceID=1311,
		order=2,
		name="Sentinel of Winter",
		lore="The seasons can be kind or cruel. Sentinel of Winter unleashes the harshest of winter storms to test all who face him. To surpass Nalorakk's second trial, endure the biting cold and defeat the embodiment of a winter storm.",
		dungeonEncounterID=3208,
