		sections={
			{id=32690,title="Overview",body="The Sentinel of Winter harnesses the power of the surrounding blizzard. This forms |cFF2959D3|Hspell:1235623|h[Raging Squalls]|h|r which wander the landscape, and Fractured Shivercores which cast |cFF2959D3|Hspell:1235829|h[Winter's Shroud]|h|r until defeated.\n\n|cFF2959D3|Hspell:1235656|h[Frozen Tempest]|h|r creates a massive storm that pulses Frost damage to all players and continously pushes them back."},
			{id=32691,title="Damage Dealers",body="$[23$bullet; Fractured Shivercores create |cFF2959D3|Hspell:1234314|h[Snowdrifts]|h|r and trigger |cFF2959D3|Hspell:1263590|h[Rimeshatter]|h|r when defeated.$]\n$[1,2$bullet; Fractured Shivercores create |cFF2959D3|Hspell:1234314|h[Snowdrifts]|h|r when defeated.$]\n$bullet;|cFF2959D3|Hspell:1235656|h[Frozen Tempest]|h|r inflicts heavy damage and pushes players back.\n$bullet;|cFF2959D3|Hspell:1235623|h[Raging Squalls]|h|r wander the landscape and inflict moderate damage."},
			{id=32692,title="Healers",body="$bullet;|cFF2959D3|Hspell:1235656|h[Frozen Tempest]|h|r inflicts heavy damage and pushes players back.\n$bullet;|cFF2959D3|Hspell:1235548|h[Glacial Torment]|h|r inflicts a large amount of damage, but can be removed by Magic-cleansing effects.\n$[23$bullet; Fractured Shivercores create |cFF2959D3|Hspell:1234314|h[Snowdrifts]|h|r and trigger |cFF2959D3|Hspell:1263590|h[Rimeshatter]|h|r when defeated.$]\n$[1,2$bullet; Fractured Shivercores create |cFF2959D3|Hspell:1234314|h[Snowdrifts]|h|r when defeated.$]"},
			{id=32693,title="Tanks",body="$[23$bullet; Fractured Shivercores create |cFF2959D3|Hspell:1234314|h[Snowdrifts]|h|r and trigger |cFF2959D3|Hspell:1263590|h[Rimeshatter]|h|r when defeated.$]\n$[1,2$bullet; Fractured Shivercores create |cFF2959D3|Hspell:1234314|h[Snowdrifts]|h|r when defeated.$]\n$bullet;|cFF2959D3|Hspell:1235656|h[Frozen Tempest]|h|r inflicts heavy damage and pushes players back.\n$bullet;|cFF2959D3|Hspell:1235623|h[Raging Squalls]|h|r wander the landscape and inflict moderate damage."},
