	[2778]={
		encounterID=2778,
		instanceID=1311,
		order=3,
		name="Nalorakk",
		lore="Slumbering in his fitful and battle-filled dream, Nalorakk, the Loa of War, will only test the mettle of the worthy. Survive his trial and receive his blessing or die trying.",
		dungeonEncounterID=3209,
		uiMapID=2513,
		pin={x=0.4738,y=0.2107},
		difficultyIDs={1,2,8,23,205},
		npcIDs={236659,245246,252394,253848,255716,255813,258703,259103,259222,259416,261451,263590,265035,266442,267798},
		displayIDs={125149,129989},
		loot={
			{itemID=256737,diffs={},faction=-1},
			{itemID=251173,diffs={},faction=-1},
			{itemID=251160,diffs={},faction=-1},
			{itemID=250229,diffs={},faction=-1},
			{itemID=251159,diffs={},faction=-1},
			{itemID=251158,diffs={},faction=-1},
			{itemID=251156,diffs={},faction=-1},
			{itemID=251173,diffs={},faction=-1},
			{itemID=251214,diffs={},faction=-1},
			{itemID=264332,diffs={},faction=-1},
		},
		sections={
			{id=33165,title="Overview",body="The Loa of War spares no mortal as the final trial, assailing players with |cFF2959D3|Hspell:1242860|h[Echoing Maul]|h|r and pushing them with |cFF2959D3|Hspell:1255385|h[Forceful Roar]|h|r.\n\nAt 100 energy, Nalorakk casts |cFF2959D3|Hspell:1243002|h[Fury of the War God]|h|r, slamming Zul'jarra across the arena and incapacitating her with |cFF2959D3|Hspell:1243063|h[Concussive Shock]|h|r. Nalorakk commands Echoes of Nalorakk to charge the defenseless Zul'jarra, casting |cFF2959D3|Hspell:1243408|h[Echoing Fury]|h|r when colliding with the first target they encounter."},
			{id=33166,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:1243002|h[Fury of the War God]|h|r sends Echoes of Nalorakk to attack Zul'jarra, stopping only to cast |cFF2959D3|Hspell:1243408|h[Echoing Fury]|h|r on the first target they encounter.\n$bullet; Each Echo of Nalorakk casts |cFF2959D3|Hspell:1242860|h[Echoing Maul]|h|r when Nalorakk casts |cFF2959D3|Hspell:1242860|h[Echoing Maul]|h|r.\n$bullet; Nalorakk's |cFF2959D3|Hspell:1255385|h[Forceful Roar]|h|r pushes all players away."},
			{id=33167,title="Healers",body="$bullet; |cFF2959D3|Hspell:1243585|h[Overwhelming Onslaught]|h|r inflicts significant damage even while protected from Zul'jarra's |cFF2959D3|Hspell:1261776|h[Defensive Stance]|h|r.\n$bullet; Each Echo of Nalorakk casts |cFF2959D3|Hspell:1242860|h[Echoing Maul]|h|r when Nalorakk casts |cFF2959D3|Hspell:1242860|h[Echoing Maul]|h|r.\n$bullet; Nalorakk's |cFF2959D3|Hspell:1255385|h[Forceful Roar]|h|r pushes all players away."},
			{id=33168,title="Tanks",body="$bullet; Zul'jarra's |cFF2959D3|Hspell:1261776|h[Defensive Stance]|h|r greatly reduces Nalorakk's |cFF2959D3|Hspell:1243585|h[Overwhelming Onslaught]|h|r.\n$bullet; |cFF2959D3|Hspell:1243002|h[Fury of the War God]|h|r sends Echoes of Nalorakk to attack Zul'jarra, stopping only to cast |cFF2959D3|Hspell:1243408|h[Echoing Fury]|h|r on the first target they encounter.\n$bullet; Each Echo of Nalorakk casts |cFF2959D3|Hspell:1242860|h[Echoing Maul]|h|r when Nalorakk casts |cFF2959D3|Hspell:1242860|h[Echoing Maul]|h|r."},
