		instanceID=1312,
		order=4,
		name="Cragpine",
		lore="Ancient as the cliffs themselves, Cragpine has slumbered for centuries beneath a canopy of towering pines. Now stirred by the careless intrusion of mortals, he rises to defend his glade, bending the forest itself to his will.",
		dungeonEncounterID=3436,
		pin={x=0.5,y=0.5},
		difficultyIDs={14},
		npcIDs={106628,112368,204484,244424},
