		},
		sections={
			{id=32613,title="Overview",body="Cragpine calls upon the treants of Zul'Aman with |cFF2959D3|Hspell:1235131|h[Rootquake]|h|r as he shakes the earth beneath his feet.\n\nThe forest itself answers his call as he awakens |cFF2959D3|Hspell:1257906|h[Ancient Seeds]|h|r slumbering in the soil."},
			{id=32614,title="Healers",body="$bullet;|cFF2959D3|Hspell:1235131|h[Rootquake]|h|r inflicts heavy damage to all players.\n$bullet;Floating |cFF2959D3|Hspell:1257906|h[Ancient Seeds]|h|r inflict damage to nearby players."},
			{id=32615,title="Tanks",body="$bullet;Cragpine inflicts heavy melee damage while wielding a |cFF2959D3|Hspell:1235144|h[War Club]|h|r.\n$bullet;Angry treants pursue players endlessly until destroyed."},
			{id=32616,title="Damage Dealers",body="$bullet;Angry treants pursue players endlessly until destroyed.\n$bullet;Floating |cFF2959D3|Hspell:1257906|h[Ancient Seeds]|h|r inflict damage to nearby players."},
			{id=34053,title="Angry Treant",body="This treant fixates on a nearby player after being rudely awakened."},
		},
	},
