		sections={
			{id=32963,title="Overview",body="Taz'Rah summons Ethereal Shades that perform |cFF2959D3|Hspell:1222098|h[Nether Dash]|h|r, damaging targets in a line in front of them.\n\nTaz'rah's |cFF2959D3|Hspell:1300259|h[Dark Bloom]|h|r causes |cFF2959D3|Hspell:1296967|h[Void Fissures]|h|r to erupt."},
			{id=32964,title="Damage Dealers",body="$bullet;Ethereal Shades periodically cast |cFF2959D3|Hspell:1222098|h[Nether Dash]|h|r on a random player, damaging targets in a line in front of them.\n$bullet;|cFF2959D3|Hspell:1300259|h[Dark Bloom]|h|r causes |cFF2959D3|Hspell:1296967|h[Void Fissures]|h|r to erupt."},
			{id=32965,title="Healers",body="$bullet;|cFF2959D3|Hspell:1222098|h[Nether Dash]|h|r strikes all players in a line and inflicts Shadow damage over a long duration.\n$bullet;|cFF2959D3|Hspell:1300259|h[Dark Bloom]|h|r inflicts heavy Shadow damage on all players and causes |cFF2959D3|Hspell:1296967|h[Void Fissures]|h|r to erupt."},
			{id=32966,title="Tanks",body="$bullet;|cFF2959D3|Hspell:1297017|h[Void Blast]|h|r inflicts heavy Shadowstrike damage.\n$bullet;|cFF2959D3|Hspell:1300259|h[Dark Bloom]|h|r causes |cFF2959D3|Hspell:1296967|h[Void Fissures]|h|r to erupt."},
