			{id=32971,title="Overview",body="Atroxus assaults players with its powerful venoms using |cFF2959D3|Hspell:1222721|h[Noxious Breath]|h|r and |cFF2959D3|Hspell:1226120|h[Poison Splash]|h|r. Its |cFF2959D3|Hspell:1262497|h[Monstrous Roar]|h|r inflicts heavy physical damage to all players summons a Toxic Creeper."},
			{id=32972,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:1222721|h[Noxious Breath]|h|r inflicts high damage in front of Atroxus.\n\n$bullet;|cFF2959D3|Hspell:1262497|h[Monstrous Roar]|h|r inflicts heavy physical damage to all players summons a Toxic Creeper to attack its target."},
			{id=32973,title="Healers",body="$bullet;|cFF2959D3|Hspell:1222642|h[Hulking Claw]|h|r inflicts high Nature damage to the primary target.\n\n$bullet;|cFF2959D3|Hspell:1222721|h[Noxious Breath]|h|r inflicts high damage in front of Atroxus."},
			{id=32974,title="Tanks",body="$bullet;|cFF2959D3|Hspell:1222642|h[Hulking Claw]|h|r inflicts high Nature damage to the primary target.\n\n$bullet;|cFF2959D3|Hspell:1282892|h[Sickening Bite]|h|r applies stacking vulnerability to Nature damage."},
