		sections={
			{id=32982,title="Overview",body="Charonus truly tests his prey to learn their limits. He attacks players using |cFF2959D3|Hspell:1248112|h[Unstable Singularity]|h|r and creates |cFF2959D3|Hspell:1263982|h[Gravitic Orbs]|h|r to hunt them down."},
			{id=32983,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:1248112|h[Unstable Singularity]|h|r inflicts Shadow damage and reduces the movement speed of players caught within it.\n\n$bullet;|cFF2959D3|Hspell:1263982|h[Gravitic Orbs]|h|r continually seek out players until collapsed by an |cFF2959D3|Hspell:1248112|h[Unstable Singularity]|h|r."},
			{id=32984,title="Healers",body="$bullet;|cFF2959D3|Hspell:1263983|h[Condensed Mass]|h|r inflicts high damage to all players.\n\n$bullet;|cFF2959D3|Hspell:1263982|h[Gravitic Orbs]|h|r continually seek out players until collapsed by an |cFF2959D3|Hspell:1248112|h[Unstable Singularity]|h|r."},
			{id=32985,title="Tanks",body="$bullet;|cFF2959D3|Hspell:1248112|h[Unstable Singularity]|h|r inflicts Shadow damage and reduces the movement speed of players caught within it.\n\n$bullet;|cFF2959D3|Hspell:1263982|h[Gravitic Orbs]|h|r continually seek out players until collapsed by an |cFF2959D3|Hspell:1248112|h[Unstable Singularity]|h|r."},
