		sections={
			{id=32994,title="Overview",body="Chimaerus wrenches its enemies into the Rift during |cFF2959D3|Hspell:1262305|h[Alndust Upheaval]|h|r where they must contend with aberrant Manifestations shielded by |cFF2959D3|Hspell:1245727|h[Alnshroud]|h|r. Manifestations that lose their shroud emerge into Reality and move towards the |cFF2959D3|Hspell:1252863|h[Insatiable]|h|r Chimaerus.\n\nUpon reaching 100 energy, Chimaerus takes to the skies with |cFF2959D3|Hspell:1245486|h[Corrupted Devastation]|h|r while summoning Manifestations below."},
			{id=32995,title="Tanks",body="$bullet; |cFF2959D3|Hspell:1262305|h[Alndust Upheaval]|h|r allows players to see into the Aln and attack Manifestations.\n$bullet; Coalesced Manifestations afflict the raid with |cFF2959D3|Hspell:1250953|h[Rift Sickness]|h|r.\n$bullet; Manifestations in Reality move toward |cFF2959D3|Hspell:1252863|h[Insatiable]|h|r Chimaerus.\n$bullet; Colossal Horrors unleash a series of |cFF2959D3|Hspell:1262020|h[Colossal Strikes]|h|r against their current target."},
			{id=32996,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:1262305|h[Alndust Upheaval]|h|r allows players to see into the Aln and attack Manifestations.\n$bullet; Coalesced Manifestations afflict the raid with |cFF2959D3|Hspell:1250953|h[Rift Sickness]|h|r.\n$bullet; Manifestations in Reality move toward |cFF2959D3|Hspell:1252863|h[Insatiable]|h|r Chimaerus."},
			{id=32997,title="Healers",body="$bullet; Coalesced Manifestations afflict the raid with |cFF2959D3|Hspell:1250953|h[Rift Sickness]|h|r.\n$bullet; |cFF2959D3|Hspell:1262305|h[Alndust Upheaval]|h|r allows players to see into the Aln and attack Manifestations.\n$bullet; Players within the Rift who are affected by |cFF2959D3|Hspell:1245698|h[Alnsight]|h|r cannot interact with allies."},
