	[2810]={
		encounterID=2810,
		instanceID=1315,
		order=0,
		name="Muro'jin and Nekraxx",
		lore="Muro'jin is a relentless tracker, charged with capturing victims for the Vilebranch's dark rites. Nekraxx, a reanimated eagle, strikes down any who resist capture by her master. They must not be allowed to supply souls for Vordaza's necrotic magic any longer.",
		dungeonEncounterID=3212,
		uiMapID=2501,
		pin={x=0.5221,y=0.6861},
		difficultyIDs={1,2,8,23,205},
		npcIDs={247570,247572},
		displayIDs={130699,130705},
		loot={
			{itemID=251167,diffs={},faction=-1},
			{itemID=251166,diffs={},faction=-1},
			{itemID=263193,diffs={},faction=-1},
			{itemID=251162,diffs={},faction=-1},
			{itemID=251176,diffs={},faction=-1},
			{itemID=251174,diffs={},faction=-1},
		},
		sections={
			{id=33348,title="Overview",body="The cunning duo of Muro'jin and Nekraxx fight as one, assailing players with an array of combined tactics.\n\nMuro'jin withers players down with |cFF2959D3|Hspell:1260643|h[Barrage]|h|r while Nekraxx flings a salvo of feathers with |cFF2959D3|Hspell:1243900|h[Fetid Quillstorm]|h|r.\n\nAs Muro'jin scatters |cFF2959D3|Hspell:1260731|h[Freezing Traps]|h|r across the arena, Nekraxx barrels forward with |cFF2959D3|Hspell:1249479|h[Carrion Swoop]|h|r."},
			{id=33349,title="Damage Dealers",body="$bullet;Muro'jin attempts to |cFF2959D3|Hspell:1249789|h[Revive Pet]|h|r upon Nekraxx's defeat, and Nekraxx enters |cFF2959D3|Hspell:1249948|h[Bestial Wrath]|h|r upon Muro'jin's defeat.\n$bullet;Muro'jin's |cFF2959D3|Hspell:1260731|h[Freezing Traps]|h|r encase players in ice upon contact. Players encased in ice can intercept Nekraxx's |cFF2959D3|Hspell:1249479|h[Carrion Swoop]|h|r.\n$bullet;Muro'jin's |cFF2959D3|Hspell:1260643|h[Barrage]|h|r follows the targeted player and affects all players in a frontal cone."},
			{id=33350,title="Healers",body="$bullet;Nekraxx's |cFF2959D3|Hspell:1246666|h[Infected Pinions]|h|r inflicts significant damage to all players.\n$bullet;Muro'jin's |cFF2959D3|Hspell:1260731|h[Freezing Traps]|h|r encase players in ice upon contact. Players encased in ice can intercept Nekraxx's |cFF2959D3|Hspell:1249479|h[Carrion Swoop]|h|r.\n$bullet;Muro'jin's |cFF2959D3|Hspell:1260643|h[Barrage]|h|r follows the targeted player and affects all players in a frontal cone."},
			{id=33351,title="Tank",body="$bullet;Muro'jin's |cFF2959D3|Hspell:1266480|h[Flanking Spear]|h|r both repositions behind his current target and applies |cFF2959D3|Hspell:1266488|h[Open Wound]|h|r.\n$bullet;Muro'jin's |cFF2959D3|Hspell:1260731|h[Freezing Traps]|h|r encase players in ice upon contact. Players encased in ice can intercept Nekraxx's |cFF2959D3|Hspell:1249479|h[Carrion Swoop]|h|r.\n$bullet;Nekraxx's |cFF2959D3|Hspell:1249479|h[Carrion Swoop]|h|r affects all players in its path, inflicting damage and knocking them upwards."},
			{id=33932,title="Muro'jin"},
			{id=34265,title="Section 7",difficultyIDs={1,2}},
			{id=33650,title="Section 7",body="$[!23\n\nIn Mythic difficulty, triggering a |cFF2959D3|Hspell:1260731|h[Freezing Trap]|h|r also creates an |cFF2959D3|Hspell:1243751|h[Icy Slick]|h|r.$]",difficultyIDs={8,23}},
			{id=34266,title="Section 19",difficultyIDs={8,23}},
			{id=34211,title="Section 15"},
			{id=34212,title="Section 16"},
			{id=33933,title="Section 12"},
