	[2811]={
		encounterID=2811,
		instanceID=1315,
		order=1,
		name="Vordaza",
		lore="Vordaza, the Vilebranch's master of souls, performs forbidden rites to extract the soul essences of the dead. She distills the suffering of her victims into raw necrotic energy to empower Rak'tul, her monstrous creation. Her vile magic and her monster must be stopped.",
		dungeonEncounterID=3213,
		uiMapID=2501,
		pin={x=0.7774,y=0.5908},
		difficultyIDs={1,2,8,23,205},
		npcIDs={248595},
		displayIDs={131548,136272},
		loot={
			{itemID=250223,diffs={},faction=-1},
			{itemID=251172,diffs={},faction=-1},
			{itemID=251171,diffs={},faction=-1},
			{itemID=251170,diffs={},faction=-1},
			{itemID=251169,diffs={},faction=-1},
			{itemID=251161,diffs={},faction=-1},
			{itemID=251178,diffs={},faction=-1},
		},
		sections={
			{id=33360,title="Overview",body="Vordaza blasts players with necrotic energy while manipulating spirits with |cFF2959D3|Hspell:1251204|h[Wrest Phantoms]|h|r to perform her bidding.\n\nAs the fight progresses, Vordaza invokes a |cFF2959D3|Hspell:1250708|h[Necrotic Convergence]|h|r, concentrating soul energy into volatile masses until interrupted."},
			{id=33361,title="Damage Dealers",body="$bullet;Vordaza summons Unstable Phantoms with |cFF2959D3|Hspell:1251204|h[Wrest Phantoms]|h|r that chase players with |cFF2959D3|Hspell:1251775|h[Final Pursuit]|h|r.\n$bullet;Unstable Phantoms afflict all players with |cFF2959D3|Hspell:1251813|h[Lingering Dread]|h|r when defeated.\n$bullet;While |cFF2959D3|Hspell:1251598|h[Deathshroud]|h|r holds, Vordaza is unable to be interrupted."},
			{id=33362,title="Healers",body="$bullet;Vordaza summons Unstable Phantoms with |cFF2959D3|Hspell:1251204|h[Wrest Phantoms]|h|r that chase players with |cFF2959D3|Hspell:1251775|h[Final Pursuit]|h|r.\n$bullet;Unstable Phantoms afflict all players with |cFF2959D3|Hspell:1251813|h[Lingering Dread]|h|r when defeated.\n$bullet;|cFF2959D3|Hspell:1251554|h[Drain Soul]|h|r inflicts heavy damage to Vordaza's current target and absorbs healing received."},
			{id=33363,title="Tank",body="$bullet;Vordaza summons Unstable Phantoms with |cFF2959D3|Hspell:1251204|h[Wrest Phantoms]|h|r that chase players with |cFF2959D3|Hspell:1251775|h[Final Pursuit]|h|r.\n$bullet;Unstable Phantoms afflict all players with |cFF2959D3|Hspell:1251813|h[Lingering Dread]|h|r when defeated.\n$bullet;|cFF2959D3|Hspell:1251554|h[Drain Soul]|h|r inflicts heavy damage to Vordaza's current target and absorbs healing received."},
			{id=33702,title="Section 6"},
			{id=34310,title="Section 14"},
			{id=34311,title="Section 15"},
			{id=33733,title="Section 7"},
			{id=33734,title="Unstable Phantom"},
