	[2812]={
		encounterID=2812,
		instanceID=1315,
		order=2,
		name="Rak'tul, Vessel of Souls",
		lore="An undead thrall bound to Vordaza, Rak'tul is grotesquely bloated with the essences of tormented souls and necrotic power. Drunk on his newfound power and driven mad by the souls' endless suffering, Rak'tul stands ready to break Zul'Aman beneath the crushing weight of his fists.",
		dungeonEncounterID=3214,
		uiMapID=2501,
		pin={x=0.7774,y=0.1008},
		difficultyIDs={1,2,8,23,205},
		npcIDs={75728,150910,171123},
		displayIDs={131550,136272,137163,137911},
		loot={
			{itemID=250258,diffs={},faction=-1},
			{itemID=251177,diffs={},faction=-1},
			{itemID=251179,diffs={},faction=-1},
