	[2813]={
		encounterID=2813,
		instanceID=1316,
		order=0,
		name="Chief Corewright Kasreth",
		lore="Chief Corewright Kasreth and the Shadowguard Ethereals once upheld flawless energy flow within the Nexus-Point's Corespark Engine. But Lothraxion's radiant disruption shattered their balance. Now, cloaked in mistrust and weary of outsiders, they labor to restore the arcane harmony that once sustained the Nexus-Point.",
		dungeonEncounterID=3328,
		uiMapID=2556,
		pin={x=0.2225,y=0.3706},
		difficultyIDs={1,2,8,23,205},
		npcIDs={241539},
		displayIDs={124026},
		loot={
			{itemID=251205,diffs={},faction=-1},
			{itemID=251206,diffs={},faction=-1},
			{itemID=251204,diffs={},faction=-1},
			{itemID=251203,diffs={},faction=-1},
			{itemID=251202,diffs={},faction=-1},
			{itemID=251201,diffs={},faction=-1},
		},
		sections={
			{id=33395,title="Overview",body="Kasreth's Corespark Engine ebbs and flows with arcane energies, forming |cFF2959D3|Hspell:1251626|h[Leyline Arrays]|h|r between the conduits around the room. The Corewright is a mastermind of circuitry, overwhelming a player with |cFF2959D3|Hspell:1251767|h[Reflux Charge]|h|r. At 100 energy, Kasreth picks up a corespark and overcharges it in the engine, unleashing a |cFF2959D3|Hspell:1257509|h[Corespark Detonation]|h|r at the impact location."},
			{id=33396,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:1251767|h[Reflux Charge]|h|r inflicts damage until overloaded.\n$bullet;|cFF2959D3|Hspell:1251183|h[Leyline Arrays]|h|r link randomly between conduits around the room and inflict heavy damage when crossing.\n$bullet;|cFF2959D3|Hspell:1264040|h[Flux Collapse]|h|r launches a continuous flow of arcane towards a player."},
			{id=33397,title="Healers",body="$bullet;|cFF2959D3|Hspell:1251767|h[Reflux Charge]|h|r inflicts damage until overloaded.\n$bullet;|cFF2959D3|Hspell:1251183|h[Leyline Arrays]|h|r link randomly between conduits around the room and inflict heavy damage when crossing.\n$bullet;|cFF2959D3|Hspell:1264040|h[Flux Collapse]|h|r launches a continuous flow of arcane towards a player."},
			{id=33398,title="Tanks",body="$bullet;|cFF2959D3|Hspell:1251767|h[Reflux Charge]|h|r inflicts damage until overloaded.\n$bullet;|cFF2959D3|Hspell:1251183|h[Leyline Arrays]|h|r link randomly between conduits around the room and inflict heavy damage when crossing.\n$bullet;|cFF2959D3|Hspell:1264040|h[Flux Collapse]|h|r launches a continuous flow of arcane towards a player."},
			{id=34752,title="Section 5"},
			{id=34895,title="Section 8",difficultyIDs={1,2}},
			{id=34896,title="Section 12"},
			{id=34065,title="Section 8",body="$[!23\n\nIn Mythic difficulty, Corespark Detonation knocks away all players.$]",difficultyIDs={23}},
			{id=34892,title="Section 12"},
			{id=33886,title="Section 7"},
			{id=34333,title="Section 9"},
			{id=34334,title="Section 10"},
			{id=33730,title="Section 6"},
		},
	},
	[2814]={
		encounterID=2814,
		instanceID=1316,
		order=0,
		name="Corewarden Nysarra",
		lore="Corewarden Nysarra guards Nexus-Point Xenas with waning strength. Lightscarred by Lothraxion's assault, she broods in her wing, wounded and waiting. The Nullward stirs with battle, and her wrath sharpens for any who dare approach.",
		dungeonEncounterID=3332,
		uiMapID=2556,
		pin={x=0.8181,y=0.3477},
		difficultyIDs={1,2,8,23,205},
		npcIDs={254227},
		displayIDs={131511,131531,137240},
		loot={
			{itemID=250253,diffs={},faction=-1},
			{itemID=251210,diffs={},faction=-1},
			{itemID=251209,diffs={},faction=-1},
			{itemID=251208,diffs={},faction=-1},
			{itemID=251207,diffs={},faction=-1},
			{itemID=251213,diffs={},faction=-1},
			{itemID=251093,diffs={},faction=-1},
		},
		sections={
			{id=33399,title="Overview",body="Scarred by her struggle with Lothraxion, Fractured Images continue to assault the Corewarden, erupting in bursts of |cFF2959D3|Hspell:1247976|h[Lightscar Flare]|h|r. Nysarra calls upon the remnants of her shattered command to defend and suppress players while she slips through the shadows with |cFF2959D3|Hspell:1249014|h[Eclipsing Step]|h|r and empowers her twin nullblades to unleash |cFF2959D3|Hspell:1247937|h[Umbral Lash]|h|r."},
			{id=33400,title="Damage Dealers",body="$bullet; Corewarden Nysarra calls to her subordinates to assist during battle.\n$bullet;|cFF2959D3|Hspell:1249014|h[Eclipsing Step]|h|r carves into nearby players in addition to the targeted victim.\n$bullet;|cFF2959D3|Hspell:1247976|h[Lightscar Flare]|h|r stuns as the Fractured Image strikes its target and the resulting wound surges with Holy energy, providing power to those standing within it."},
			{id=33401,title="Healers",body="$bullet; Corewarden Nysarra calls to her subordinates to assist during battle.\n$bullet;|cFF2959D3|Hspell:1249014|h[Eclipsing Step]|h|r carves into nearby players in addition to the targeted victim.\n$bullet;|cFF2959D3|Hspell:1247976|h[Lightscar Flare]|h|r stuns as the Fractured Image strikes its target and the resulting wound surges with Holy energy, providing power to those standing within it."},
			{id=33402,title="Tanks",body="$bullet; Corewarden Nysarra calls to her subordinates to assist during battle.\n$bullet;The power of |cFF2959D3|Hspell:1247937|h[Umbral Lash]|h|r cleaves nearby players and applies |cFF2959D3|Hspell:1252828|h[Void Gash]|h|r.\n$bullet;|cFF2959D3|Hspell:1247976|h[Lightscar Flare]|h|r stuns as the Fractured Image strikes its target and the resulting wound surges with Holy energy, providing power to those standing within it."},
			{id=34346,title="Section 14"},
			{id=34494,title="Section 5",difficultyIDs={1,2}},
			{id=33460,title="Section 5",body="$[!23\n\nIn Mythic difficulty, Nysarra devours the unworthy at the end of Lightscar Flare.$]",difficultyIDs={23}},
			{id=34054,title="Section 13",difficultyIDs={23}},
