	[2815]={
		encounterID=2815,
		instanceID=1316,
		order=0,
		name="Lothraxion",
		lore="Blinded by betrayal, Lothraxion storms the Nexus-Point alone. With its defenses shattered, he prepares to breach the Nexus Core, risking a chain eruption that could annihilate Silvermoon and ripple across Azeroth itself.",
		dungeonEncounterID=3333,
		uiMapID=2556,
		pin={x=0.5135,y=0.2792},
		difficultyIDs={1,2,8,23,205},
		npcIDs={241546},
		displayIDs={137513,137705},
