		sections={
			{id=34883,title="Overview",body="Lu'ashal assails foes in a holy frenzy, raining energy from the skies with |cFF2959D3|Hspell:1243963|h[Radiant Sunder]|h|r  to shatter the ground that leave |cFF2959D3|Hspell:1243988|h[Blinding Fissures]|h|r behind. During |cFF2959D3|Hspell:1258427|h[Radiant Flare]|h|r, she unleashes waves of |cFF2959D3|Hspell:1258426|h[Radiant Embers]|h|r that travel across the battlefield."},
			{id=34884,title="Healers",body="$bullet; |cFF2959D3|Hspell:1276436|h[Dawncrazed Halo]|h|r inflicts moderate damage in an area around afflicted players.\n$bullet; |cFF2959D3|Hspell:1258427|h[Radiant Flare]|h|r inflicts substantial damage and casues |cFF2959D3|Hspell:1258426|h[Radiant Embers]|h|r to erupt from |cFF2959D3|Hspell:1243988|h[Blinding Fissures]|h|r ."},
			{id=34885,title="Tanks",body="$bullet; |cFF2959D3|Hspell:1276373|h[Dawnfire Breath]|h|r inflicts heavy Radiant damage in a cone at the primary target.\n$bullet; |cFF2959D3|Hspell:1258427|h[Radiant Flare]|h|r inflicts substantial damage and casues |cFF2959D3|Hspell:1258426|h[Radiant Embers]|h|r to erupt from |cFF2959D3|Hspell:1243988|h[Blinding Fissures]|h|r ."},
			{id=34886,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:1276436|h[Dawncrazed Halo]|h|r inflicts moderate damage in an area around afflicted players.\n$bullet; |cFF2959D3|Hspell:1258427|h[Radiant Flare]|h|r inflicts substantial damage and casues |cFF2959D3|Hspell:1258426|h[Radiant Embers]|h|r to erupt from |cFF2959D3|Hspell:1243988|h[Blinding Fissures]|h|r ."},
