		sections={
			{id=34925,title="Overview",body="Predaxas thrashes about the Gorging Pit ejecting his late lunch at foes with |cFF2959D3|Hspell:1276193|h[Regurgitation]|h|r and crushing vermin with |cFF2959D3|Hspell:1276320|h[Seismic Slam]|h|r."},
			{id=34926,title="Tanks",body="$bullet;|cFF2959D3|Hspell:1276193|h[Regurgitation]|h|r ejects Predaxas' previous meals which attack players.\n$bullet;|cFF2959D3|Hspell:1276320|h[Seismic Slam]|h|r knocks back players and Predaxas' previous meals, causing additional effects."},
			{id=34927,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:1276320|h[Seismic Slam]|h|r knocks back players and Predaxas' previous meals, causing additional effects.\n$bullet;Voidticks react to |cFF2959D3|Hspell:1276320|h[Seismic Slam]|h|r triggering |cFF2959D3|Hspell:1276884|h[Voidscatter]|h|r."},
			{id=34928,title="Healers",body="$bullet;Reguritated Bloodclaws periodically gain |cFF2959D3|Hspell:1277711|h[Bestial Rage]|h|r inflicting increased damage.\n$bullet;|cFF2959D3|Hspell:1276320|h[Seismic Slam]|h|r knocks back players and Predaxas' previous meals, causing additional effects."},
