		sections={
			{id=34055,title="Overview",body="Thorm'belan unleashes the power of the Light to assault the players. Periodically lobbing |cFF2959D3|Hspell:1257825|h[Scintillating Shards]|h|r while also pulling players in towards itself with |cFF2959D3|Hspell:1258639|h[Shredding Tendrils]|h|r."},
			{id=34056,title="Tanks",body="$bullet; |cFF2959D3|Hspell:1257825|h[Scintillating Shard]|h|r causes all players to become stunned if it is not intercepted.\n$bullet; |cFF2959D3|Hspell:1258639|h[Shredding Tendrils]|h|r pulls players towards Thorm'belan and inflicts damage until players move far enough away from Thorm'belan.\n$bullet; |cFF2959D3|Hspell:1257320|h[Radiant Mote]|h|r damages and disorients nearby players when it expires."},
			{id=34057,title="Healers",body="$bullet; |cFF2959D3|Hspell:1257825|h[Scintillating Shard]|h|r causes all players to become stunned if it is not intercepted.\n$bullet; |cFF2959D3|Hspell:1258639|h[Shredding Tendrils]|h|r pulls players towards Thorm'belan and inflicts damage until players move far enough away from Thorm'belan.\n$bullet; |cFF2959D3|Hspell:1257320|h[Radiant Mote]|h|r damages and disorients nearby players when it expires."},
			{id=34058,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:1257825|h[Scintillating Shard]|h|r causes all players to become stunned if it is not intercepted.\n$bullet; |cFF2959D3|Hspell:1258639|h[Shredding Tendrils]|h|r pulls players towards Thorm'belan and inflicts damage until players move far enough away from Thorm'belan.\n$bullet; |cFF2959D3|Hspell:1257320|h[Radiant Mote]|h|r damages and disorients nearby players when it expires."},
