		sections={
			{id=34109,title="Overview",body="Nymrissa Wavecaller creates an |cFF2959D3|Hspell:1257717|h[Alluring Bubble]|h|r within the grotto that lures nearby murlocs into her grasp. She then summons |cFF2959D3|Hspell:1258668|h[Swirling Whirlpools]|h|r to break the bubble, empowering murlocs within."},
			{id=35757,title="Tank",body="$bullet;|cFF2959D3|Hspell: 1258901|h[Water Jet]|h|r inflicts sustained damage to Nymrissa Wavecaller's current target, and removes icy patches of |cFF2959D3|Hspell: 1257654|h[Lingering Frost]|h|r.\n$bullet;|cFF2959D3|Hspell: 1257717|h[Alluring Bubble]|h|r attracts a large group of Bubblefin Shorerunners to rush toward the giant bubble.",difficultyIDs={233}},
			{id=34110,title="Tank",body="$bullet;|cFF2959D3|Hspell: 1282937|h[Iceblade Flurry]|h|r inflicts sustained damage to Nymrissa Wavecaller's current target.\n$bullet;|cFF2959D3|Hspell: 1257717|h[Alluring Bubble]|h|r attracts a large group of Bubblefin Shorerunners to rush toward the giant bubble.",difficultyIDs={14,15,250}},
			{id=36631,title="Healer",body="$bullet;|cFF2959D3|Hspell: 1260837|h[Abyssal Rain]|h|r inflicts significant damage to all players.\n$bullet;|cFF2959D3|Hspell: 1257717|h[Alluring Bubble]|h|r inflicts a large burst of damage to all players when it |cFF2959D3|Hspell: 1258150|h[Pops!]|h|r"},
			{id=34111,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell: 1257717|h[Alluring Bubble]|h|r attracts a large group of Bubblefin Shorerunners to rush toward the giant bubble.\n$bullet;Murlocs that enter a |cFF2959D3|Hspell: 1257717|h[Alluring Bubble]|h|r become empowered."},
