		sections={
			{id=34947,title="Overview",body="The Sentinel Golems of Ula'tek are filled with the caustic venoms flowing throughout the temple. The Breath of Ula'tek animates venom to destroy invaders while the Blood of Ula'tek infects players with deadly toxins. \n\nAt 100 energy the Sentinels come together to fill their venom levels with |cFF2959D3|Hspell:1284588|h[Vitriolic Stasis]|h|r, restoring health to the weaker Sentinel and infecting all players with |cFF2959D3|Hspell:1284590|h[Helical Toxins]|h|r."},
			{id=34948,title="Tanks",body="$bullet;|cFF2959D3|Hspell:1284434|h[Toxic Droplets]|h|r sprays droplets of venom in front of the Breath of Ula'tek.\n$bullet;|cFF2959D3|Hspell:1284458|h[Empowering Slam]|h|r and |cFF2959D3|Hspell:1284487|h[Bloodvenom Injection]|h|r increase in intensity each time they strike the same target.\n$bullet;|cFF2959D3|Hspell:1284590|h[Helical Toxins]|h|r is neutralized harmlessly upon reaching exactly $1284590s1 applications."},
			{id=34949,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:1284251|h[Venom Coagulation]|h|r creates a massive slime that uses |cFF2959D3|Hspell:1284257|h[Contaminate]|h|r until it is destroyed.\n$bullet;|cFF2959D3|Hspell:1284588|h[Vitriolic Stasis]|h|r restores health to the weaker Sentinel until it matches the healthier Sentinel.\n$bullet;|cFF2959D3|Hspell:1284590|h[Helical Toxins]|h|r is neutralized harmlessly upon reaching exactly $1284590s1 applications."},
			{id=34950,title="Healers",body="$bullet;|cFF2959D3|Hspell:1284471|h[Blighted Blood]|h|r infects players and can be dispelled.\n$bullet;|cFF2959D3|Hspell:1284590|h[Helical Toxins]|h|r is neutralized harmlessly upon reaching exactly $1284590s1 applications.\n$bullet;|cFF2959D3|Hspell:1284257|h[Contaminate]|h|r inflicts a high amount of damage to all players."},
			{id=35867,title="Vashnik the Malignant",body="Constantly seeking to improve his toxins, Vashnik infects players and obfuscates their attempts to save themselves.",difficultyIDs={16}},
