	[2878]={
		encounterID=2878,
		instanceID=1322,
		order=1,
		name="Rav'i",
		lore="This ravenous hydra has survived this cursed place through scavenging the meat of the fallen. That doesn't mean it is not a fearsome combatant, eager to add some fresh temple explorers to its otherwise rotting diet.",
		dungeonEncounterID=3456,
		uiMapID=2588,
		pin={x=0.4881,y=0.7929},
		difficultyIDs={1,2,8,23,205},
		npcIDs={259445},
		displayIDs={144110},
		loot={
			{itemID=273796,diffs={},faction=-1},
			{itemID=273795,diffs={},faction=-1},
			{itemID=273785,diffs={},faction=-1},
			{itemID=273775,diffs={},faction=-1},
			{itemID=273777,diffs={},faction=-1},
			{itemID=273780,diffs={},faction=-1},
			{itemID=273793,diffs={},faction=-1},
		},
		sections={
			{id=35019,title="Overview",body="Rav'i's domain is littered with Carrion Piles from the many sacrificed creatures thrown into the pit. Occasionally, Rav'i makes a |cFF2959D3|Hspell:1307915|h[Ravenous Stomp]|h|r, dropping |cFF2959D3|Hspell:1307703|h[Fresh Meat]|h|r.\n\nUpon running out of energy, Rav'i begins |cFF2959D3|Hspell:1298221|h[Ssscavenging]|h|r from the nearest Carrion Pile. If the Carrion Pile contains |cFF2959D3|Hspell:1307703|h[Fresh Meat]|h|r, Rav'i goes into a |cFF2959D3|Hspell:1307765|h[Feeding Frenzy]|h|r."},
			{id=35020,title="Tanks",body="$bullet; |cFF2959D3|Hspell:1307915|h[Ravenous Stomp]|h|r drops |cFF2959D3|Hspell:1307703|h[Fresh Meat]|h|r on some Carrion Piles.\n$bullet; Carrion Piles with |cFF2959D3|Hspell:1307703|h[Fresh Meat]|h|r cause Rav'i to go into a |cFF2959D3|Hspell:1307765|h[Feeding Frenzy]|h|r.\n$bullet; Rav'i inflicts melee damage with |cFF2959D3|Hspell:1298683|h[Hydrastrike]|h|r."},
			{id=35021,title="Damage Dealers",body="$bullet; Rav'i stops |cFF2959D3|Hspell:1298221|h[Ssscavenging]|h|r or her |cFF2959D3|Hspell:1307765|h[Feeding Frenzy]|h|r when her absorb shield is removed.\n$bullet; |cFF2959D3|Hspell:1298221|h[Ssscavenging]|h|r and |cFF2959D3|Hspell:1307765|h[Feeding Frenzy]|h|r both continuously apply |cFF2959D3|Hspell:1307700|h[Carrion Burst]|h|r to all players until stopped.\n$bullet; |cFF2959D3|Hspell:1296069|h[Regurgitate]|h|r hurls waves of acid in a player's direction."},
			{id=35022,title="Healers",body="$bullet; |cFF2959D3|Hspell:1297876|h[Triple Shot]|h|r inflicts damage around 3 players over time.\n$bullet; While Rav'i is eating, she afflicts all players with increasing applications of |cFF2959D3|Hspell:1307700|h[Carrion Burst]|h|r and is a |cFF2959D3|Hspell:1306345|h[Messy Eater]|h|r.\n$bullet; |cFF2959D3|Hspell:1296069|h[Regurgitate]|h|r hurls waves of acid in a player's direction."},
			{id=35023,title="Ssscavenging"},
