	[2879]={
		encounterID=2879,
		instanceID=1322,
		order=2,
		name="The Writhing Coil",
		lore="In the feeding frenzy upon each other, there has been one Child of Ula'tek that has proved victorious over the rest of the brood. With every battle won, the twisting monstrosity known as the Writhing Coil only grows stronger.",
		dungeonEncounterID=3457,
		uiMapID=2589,
		pin={x=0.6976,y=0.5179},
		difficultyIDs={1,2,8,23,205},
		npcIDs={259446},
		displayIDs={147556},
		loot={
			{itemID=273781,diffs={},faction=-1},
