	[2880]={
		encounterID=2880,
		instanceID=1322,
		order=3,
		name="Zul'jan",
		lore="With the Fang of Ula'tek, Zul'jan performs the final ritual to gain the power to release the monstrous weapon his ancestors sealed away thousands of years ago. Still held in the sway of the spirit of Malacrass, Zul'jan is unaware that the Fang is also the only hope for his sister Zul'jarra's survival.",
		dungeonEncounterID=3458,
		uiMapID=2590,
		pin={x=0.4595,y=0.1785},
		difficultyIDs={1,2,8,23,205},
		npcIDs={259447},
		displayIDs={145435},
		loot={
