	[2888]={
		encounterID=2888,
		instanceID=1320,
		order=1,
		name="Nek'zali the Soulcoiler",
		lore="Long ago, the shadow hunter Nek'zali and her followers were entombed for the blasphemous act of summoning Ula'tek. Restored by the very power she unleashed, she calls the other Soulcoilers from their tombs to serve her once more.",
		dungeonEncounterID=3470,
		uiMapID=2606,
		pin={x=0.5032,y=0.5017},
		difficultyIDs={14,15,16,17,220,241},
