			{id=37171,title="Restless Amani",body="Ancient spirits return to their corpses, and make their way towards the |cFF2959D3|Hspell:1284032|h[Soulcoil Well]|h|r.\n$[!15,16\n On Heroic difficulty, Raised Amani corpses remain on the ground upon defeat as |cFF2959D3|Hspell:1295263|h[Vessels of Awakening]|h|r.$]"},
			{id=37172,title="Section 98",difficultyIDs={15,16}},
			{id=37173,title="Section 22"},
