			{id=36595,title="Section 51"},
			{id=36196,title="Section 14"},
			{id=35255,title="Intermission: Ritual of Awakening",body="Upon reaching 50% health, Nek'zali retreats to the Soulcoil Well and summons an Echo of Jawae that protects her from harm."},
			{id=36576,title="Echo of Jawae",body="A spectral echo that protects Nek'zali from harm. Defeating an Echo of Jawae severs their Tether of Awakening."},
			{id=36582,title="Section 97"},
			{id=36577,title="Section 50"},
			{id=37141,title="Section 78",body="$[!15,16\n\nOn Heroic difficulty, |cFF2959D3|Hspell:1294933|h[Slithering Flame]|h|r combusts into |cFF2959D3|Hspell:1289875|h[Cremation]|h|r upon expiration.$]",difficultyIDs={15,16}},
